# ---------------------------------------------------------------- L3
written("w11_gamma_vs_radio_danger", 11, 3, "11d",
        stem="Explain why gamma rays are far more hazardous to living cells than radio waves.",
        points=[P("gamma rays have a much higher frequency, so each wave carries much more energy", ["higher frequency", "high frequency", "more energy", "high energy", "shorter wavelength"]),
                P("they are ionising: they can knock electrons out of atoms and damage or kill cells / DNA", ["ionis", "ioniz", "knock electrons", "remove electrons", "damage cells", "kill cells", "dna", "mutation", "cancer"]),
                P("radio waves have low frequency and energy and are not ionising", ["radio low", "radio waves are not ionising", "not ionising", "low energy", "low frequency", "too little energy"])],
        min_points=2,
        model_answer="Gamma rays have a very high frequency, so they carry much more energy than radio waves. They are ionising: they can remove electrons from atoms, damaging or killing living cells and causing mutations or cancer. Radio waves have very low frequency and energy and are not ionising.",
        hints=["Compare the two regions: which has the higher frequency, and what does that mean for the energy carried?",
               "High-energy radiation can change atoms in a cell. What is that effect called?",
               "Explain the energy difference, name the effect on cells, and contrast with radio waves."],
        keywords="high frequency = high energy, ionising, damages cells; radio not ionising",
        sample_pass=["Gamma rays have a much higher frequency and energy so they are ionising and can damage cells and DNA, while radio waves are not ionising",
                     "gamma carries far more energy and can knock electrons out of atoms, killing cells; radio waves have too little energy to do this"],
        sample_fail=["Gamma rays are hotter", "Radio waves cannot pass through the body"])

